	"exactCanonicalProfileBytes",
	"exactCanonicalSignerSetBytes",
	"genesisAnchorDigest",
	"kind",
	"objectId",
	"profileId",
	"quorum",
	"version",
]);

export type CreatorCheckpointFailureReason =
	| "commit-qc-rejected"
	| "current-rejected"
	| "custody-unavailable"
	| "expected-head-mismatch"
	| "genesis-rejected"
	| "lineage-invalid"
	| "malformed-input"
