		expect(entries(activeCensus, "drp-seal-qc", 0, "commit")).toHaveLength(0);
		expect(entries(activeCensus, "drp-v3-latched-acl", 0)).toHaveLength(0);
		expect(entries(activeCensus, "drp-v3-latched-acl", 1)).toHaveLength(1);
120→	});

